# Build transformed grid from manually transcribed test components; rows/cols are zero-based.
N=22
grid=[[0]*N for _ in range(N)]
objs={
 1: ([(3,c) for c in (3,4,5)]+[(4,c) for c in (3,5)]+[(5,c) for c in (3,5)], [(6,3),(6,5)], (1,9)),
 5: ([(11,c) for c in range(2,6)]+[(12,c) for c in (2,5)]+[(13,2),(14,2),(15,2),(15,3)], [(10,2),(10,5),(13,5),(15,4)], (-3,4)),
 4: ([(r,c) for r in range(11,14) for c in range(9,12)], [(10,9),(10,10),(12,8),(12,12)], (0,0)),
 9: ([(13,c) for c in range(15,20)]+[(14,15),(14,19),(15,19),(16,19),(17,18),(17,19)], [(12,17),(12,19),(15,15),(17,17)], (-5,-5)),
 6: ([(18,c) for c in range(9,13)]+[(19,9),(19,12)], [(20,9),(20,12)], (-13,-3)),
}
collisions=[]
for col,(cells,marks,(dr,dc)) in objs.items():
    for r,c in cells:
        rr,cc=r+dr,c+dc
        if not(0<=rr<N and 0<=cc<N): print('out of bounds',col,rr,cc)
        if grid[rr][cc] not in (0,col): collisions.append((rr,cc,grid[rr][cc],col))
        grid[rr][cc]=col
    for r,c in marks:
        rr,cc=r+dr,c+dc
        if not(0<=rr<N and 0<=cc<N): print('marker out of bounds',col,rr,cc)
        if grid[rr][cc] not in (0,2): collisions.append((rr,cc,grid[rr][cc],2))
        grid[rr][cc]=2
print('collisions',collisions)
for r,row in enumerate(grid):
    if any(row): print(r, row)
